from pathlib import Path
import html
out=Path('db-demo/docs');out.mkdir(parents=True,exist_ok=True)
def svg(inner,h=320):
 return f'<svg viewBox="0 0 800 {h}" role="img" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;font-family:Hiragino Sans,Meiryo,sans-serif">'+inner+'</svg>'
def box(x,y,w,h,text='',fill='#ffffff',stroke='#b9cbc5',size=19):
 return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="12" fill="{fill}" stroke="{stroke}"/>'+ (f'<text x="{x+18}" y="{y+34}" font-size="{size}" fill="#253b47">{html.escape(text)}</text>' if text else '')
def t(x,y,text,size=18,fill='#253b47',weight='400'):
 return f'<text x="{x}" y="{y}" font-size="{size}" font-weight="{weight}" fill="{fill}">{html.escape(text)}</text>'
def n(x,y,num):
 return f'<circle cx="{x}" cy="{y}" r="18" fill="#14776a"/>'+t(x-6,y+7,str(num),19,'#fff','700')
def arrow(x,y,x2,y2):
 return f'<path d="M{x} {y} L{x2} {y2}" stroke="#14776a" stroke-width="4" fill="none" marker-end="url(#a)"/>'
defs='<defs><marker id="a" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0 0 L6 3 L0 6" fill="#14776a"/></marker></defs>'
